-- RecipeDB: every profession recipe in WoW Forever (Data/Recipes.lua,
-- generated by tools/recipes.js from the game's own data tables via
-- wago.tools), plus search over names, the window's groups and materials.
--
-- Only IDs are bundled. Names, icons and quality come from the player's own
-- game at runtime (async, through CraftIndex's name cache), so they're
-- always right and in the player's language. A recipe the running client
-- says doesn't exist (C_Spell.DoesSpellExist) is hidden.
local _, SK = ...

local DB = SK:NewModule("RecipeDB")
local Compat = SK.Compat

DB.MIN_QUERY = 3
DB.MAX_RESULTS = 300
DB.REQUESTS_PER_SEARCH = 200 -- name loads asked for per search (the rest follow as names arrive)

local byID, all, byProf
local catNames = {}

-- Entry: { recipeID, skillLine, itemID, cat, reag = "item:count,..." }
local function index()
	if byID then return end
	byID, all, byProf = {}, {}, {}
	for skillLine, list in pairs(SK.Data.RECIPE_LIST or {}) do
		byProf[skillLine] = {}
		for _, e in ipairs(list) do
			local r = { recipeID = e[1], skillLine = skillLine, itemID = e[2] or 0, cat = e[3], reag = e[4] or "" }
			if not byID[r.recipeID] then
				byID[r.recipeID] = r
				all[#all + 1] = r
				byProf[skillLine][#byProf[skillLine] + 1] = r
			end
		end
	end
end

function DB.Reset() byID, all, byProf, catNames = nil, nil, nil, {} end

function DB.Count() index(); return #all end
function DB.Get(recipeID) index(); return byID[recipeID] end

-- Recipes of one profession (or all), skipping ones this client doesn't have.
function DB.List(skillLine)
	index()
	local src = skillLine and (byProf[skillLine] or {}) or all
	local out = {}
	for _, r in ipairs(src) do
		if Compat.SpellExists(r.recipeID) ~= false then out[#out + 1] = r end
	end
	return out
end

-- { { itemID, qty } } from the bundled data.
function DB.Reagents(recipeID)
	local r = DB.Get(recipeID)
	local out = {}
	if not r then return out end
	for id, n in r.reag:gmatch("(%d+):(%d+)") do out[#out + 1] = { itemID = tonumber(id), qty = tonumber(n) } end
	return out
end

-- The window's group name ("Camping"), from the game when it can say
-- (localised), else the bundled English name.
function DB.CategoryName(cat)
	if not cat then return nil end
	if catNames[cat] == nil then
		catNames[cat] = Compat.CategoryInfo(cat) or false
	end
	if catNames[cat] then return catNames[cat] end
	local c = SK.Data.RECIPE_CATS and SK.Data.RECIPE_CATS[cat]
	return c and c[1] or nil
end

function DB.WowheadURL(recipeID, itemID)
	if itemID and itemID > 0 then return "https://www.wowhead.com/forever/item=" .. itemID end
	return "https://www.wowhead.com/forever/spell=" .. recipeID
end

---------------------------------------------------------------------------
-- Search
---------------------------------------------------------------------------
local function lower(s) return s and s:lower() or nil end

-- Which part matched: "name", "group" or "material" (with the material's name).
local function matchOf(r, q, CI)
	local name = (r.itemID > 0 and CI.ItemName(r.itemID)) or CI.SpellName(r.recipeID)
	if name and lower(name):find(q, 1, true) then return "name", nil, name end
	local spell = CI.SpellName(r.recipeID)
	if spell and spell ~= name and lower(spell):find(q, 1, true) then return "name", nil, name or spell end
	local group = DB.CategoryName(r.cat)
	if group and lower(group):find(q, 1, true) then return "group", group, name end
	for id in r.reag:gmatch("(%d+):%d+") do
		local m = CI.ItemName(tonumber(id))
		if m and lower(m):find(q, 1, true) then return "material", m, name end
	end
	return nil, nil, name
end

-- query: text (at least MIN_QUERY letters, unless a profession is picked);
-- skillLine: nil = every profession. Returns rows, state, loading:
--   state "short" (type more) or "ok"; loading = recipes whose name hasn't
--   arrived yet (they may match once it does).
-- Row: { recipeID, itemID, skillLine, cat, name, group, count, fav, match, matched }
function DB.Search(query, skillLine, craftIndex)
	local CI = SK.CraftIndex
	craftIndex = craftIndex or CI:Get()
	query = lower((query or ""):gsub("^%s+", ""):gsub("%s+$", ""))
	if #query < DB.MIN_QUERY and not skillLine then return {}, "short", 0 end
	CI.SetBudget(DB.REQUESTS_PER_SEARCH)
	local rows, loading = {}, 0
	for _, r in ipairs(DB.List(skillLine)) do
		local match, matched, name
		if query == "" then
			name = (r.itemID > 0 and CI.ItemName(r.itemID)) or CI.SpellName(r.recipeID)
			match = "all"
		else
			match, matched, name = matchOf(r, query, CI)
		end
		if not name then loading = loading + 1 end
		if match then
			local known = craftIndex.recipes[r.recipeID]
			rows[#rows + 1] = { recipeID = r.recipeID, itemID = r.itemID, skillLine = r.skillLine, cat = r.cat,
				name = name or "...", group = DB.CategoryName(r.cat) or "", count = known and #known.crafters or 0,
				fav = SK.Favourites.IsRecipe(r.recipeID), match = match, matched = matched }
		end
	end
	CI.SetBudget(nil)
	table.sort(rows, function(a, b)
		if (a.name == "...") ~= (b.name == "...") then return b.name == "..." end
		if a.name ~= b.name then return a.name < b.name end
		return a.recipeID < b.recipeID
	end)
	for i = #rows, DB.MAX_RESULTS + 1, -1 do rows[i] = nil end
	return rows, "ok", loading
end
